import os, sys, email
from multiprocessing import Pool
import docx, openpyxl, pptx
SRC='/workspace/documents'; DST='/workspace/txt'
def conv(p):
    out=os.path.join(DST, os.path.relpath(p,SRC))+'.txt'
    os.makedirs(os.path.dirname(out),exist_ok=True)
    try:
        ext=p.rsplit('.',1)[-1]
        t=[]
        if ext=='docx':
            d=docx.Document(p)
            for para in d.paragraphs: t.append(para.text)
            for tb in d.tables:
                for r in tb.rows: t.append(' | '.join(c.text for c in r.cells))
        elif ext=='xlsx':
            wb=openpyxl.load_workbook(p,data_only=True)
            for ws in wb:
                t.append('## '+ws.title)
                for r in ws.iter_rows(values_only=True):
                    if any(v is not None for v in r): t.append(' | '.join('' if v is None else str(v) for v in r))
        elif ext=='pptx':
            pr=pptx.Presentation(p)
            for s in pr.slides:
                for sh in s.shapes:
                    if sh.has_text_frame: t.append(sh.text_frame.text)
        elif ext=='eml':
            t.append(open(p,errors='ignore').read())
        open(out,'w').write('\n'.join(t))
    except Exception as e:
        open(out,'w').write('ERR '+str(e))
fs=[os.path.join(dp,f) for dp,_,fn in os.walk(SRC) for f in fn]
with Pool(4) as pl: pl.map(conv,fs,chunksize=50)
print(len(fs))
EOF
